package com.alpharip.staffmod.IncidentPostMortemBoard; public final class IncidentLesson { private String id,lesson,category,author; private long createdAt; public IncidentLesson(){} public IncidentLesson(String i,String l,String c,String a,long t){id=req(i);lesson=req(l);category=clean(c);author=clean(a);if(t<=0)throw new IllegalArgumentException("Timestamp must be positive");createdAt=t;} public String getId(){return id;} public String getLesson(){return lesson;} public String getCategory(){return category;} public String getAuthor(){return author;} public long getCreatedAt(){return createdAt;} private static String req(String s){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException("Required value missing");return s.trim();} private static String clean(String s){return s==null?"":s.trim();} }